    SunExp_RegisterDynamicMethod(config, "SunExp_GetCurrentMapLevelNumber", SunExp_GetCurrentMapLevelNumber)
    SunExp_RegisterDynamicMethod(config, "SunExp_HasWunaEventInCurrentLevel", SunExp_HasWunaEventInCurrentLevel)
    SunExp_RegisterDynamicMethod(config, "SunExp_MarkWunaEventInCurrentLevel", SunExp_MarkWunaEventInCurrentLevel)
    SunExp_RegisterDynamicMethod(config, "SunExp_AdvanceWunaEvent", SunExp_AdvanceWunaEvent)
